/// <summary>
/// Scoped service (per-circuit) that provides low-stock alert counts
/// and broadcasts changes so every subscribed component updates together.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random s_rng = new();

    public int LastLowStockCount { get; private set; }

    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a DB call — returns a random number 0–15.
        return Task.FromResult(s_rng.Next(0, 16));
    }

    /// <summary>
    /// Fetches a fresh count for the given warehouse and notifies all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LastLowStockCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertCountChanged is not null) await OnAlertCountChanged.Invoke();
    }
}

