@using sv_df006d7d207048c99f57510d6bd60d77.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            await WarehouseState.SetWarehouseAsync(id);
            // Immediately refresh alerts for the new warehouse.
            await AlertService.RefreshAsync(id);
        }
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

@using sv_df006d7d207048c99f57510d6bd60d77.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge rounded-pill @BadgeClass">
    🔔 @AlertService.LastLowStockCount low-stock
</span>

@code {
    private string BadgeClass =>
        AlertService.LastLowStockCount > 0 ? "bg-danger" : "bg-success";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
    }
}

