@using sv_df006d7d207048c99f57510d6bd60d77.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock items:
            <span class="badge @CountBadgeClass fs-5">@AlertService.LastLowStockCount</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 s &mdash; last check: @_lastChecked?.ToString("T")
        </p>
    </div>
</div>

@code {
    private System.Threading.Timer? _timer;
    private DateTime? _lastChecked;

    private string CountBadgeClass =>
        AlertService.LastLowStockCount > 0 ? "bg-danger" : "bg-success";

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to both services so the page re-renders on any change.
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;

        // Initial fetch.
